notes.content:
{
  "root": {
    "data": {
      "id": "1708182777053",
      "text": "VIM"
    },
    "children": [
      {
        "data": {
          "id": "cz7ga1sfqtk0",
          "text": "光标移动"
        },
        "children": [
          {
            "data": {
              "id": "cz7ga76h1s80",
              "text": "1. 上下左右"
            },
            "children": [
              {
                "data": {
                  "id": "d2o2zaf9ou80",
                  "text": "hjkl 做下右上"
                },
                "children": []
              }
            ]
          },
          {
            "data": {
              "id": "cz7gabdhpbk0",
              "text": "2. 单词跳转"
            },
            "children": [
              {
                "data": {
                  "id": "cz88dh21wio0",
                  "text": "w下一个单词首，b上一个单词首"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz88dilrlew0",
                  "text": "e跳转下一个单词尾，ge上一个单词尾"
                },
                "children": []
              }
            ]
          },
          {
            "data": {
              "id": "cz7gaftiewo0",
              "text": "3. 跳转到指定行"
            },
            "children": [
              {
                "data": {
                  "id": "cz7garh0as80",
                  "text": ":12"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz7gat5nvw80",
                  "text": "12gg"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz7gaujv0go0",
                  "text": "12G"
                },
                "children": []
              }
            ]
          },
          {
            "data": {
              "id": "cz7gp3xli880",
              "text": "4. 跳转文档首、尾"
            },
            "children": [
              {
                "data": {
                  "id": "cz7gpemat1c0",
                  "text": "gg跳转文档首"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz7gpj4cwm80",
                  "text": "G跳转文档尾"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz7hbmkyxwo0",
                  "text": "Shift + g"
                },
                "children": []
              }
            ]
          },
          {
            "data": {
              "id": "cz7gpq1gkps0",
              "text": "5. 跳转行首、尾"
            },
            "children": [
              {
                "data": {
                  "id": "cz7gpu7p4ow0",
                  "text": "0跳转到第一列"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz7gpz2krco0",
                  "text": "^跳转到该行首字符"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz7gt8c7e6g0",
                  "text": "$跳转到该行尾字符"
                },
                "children": []
              }
            ]
          },
          {
            "data": {
              "id": "cz7gu6kak200",
              "text": "6.  行内字符定位"
            },
            "children": [
              {
                "data": {
                  "id": "cz7gubuns1c0",
                  "text": "f{char}"
                },
                "children": [
                  {
                    "data": {
                      "id": "d02e60pe5cw0",
                      "text": "直接定位到下一个目标字符"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "d02e6a7bdu00",
                  "text": "F{char}"
                },
                "children": [
                  {
                    "data": {
                      "id": "d02e6cnrzm80",
                      "text": "直接定位到上一个目标字符"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "d02e6mi4evk0",
                  "text": "t{char}"
                },
                "children": [
                  {
                    "data": {
                      "id": "d02e6o36nfc0",
                      "text": "定位到下一个目标字符的上一个字符"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "d02e6t2a1m00",
                  "text": "T{char}"
                },
                "children": [
                  {
                    "data": {
                      "id": "d02e6vnzahk0",
                      "text": "定位到上一个目标字符的上一个字符"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "cz7h3z1w3o00",
                  "text": ";定位下一个字符"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz7h43h4avs0",
                  "text": ",定位上一个字符"
                },
                "children": []
              }
            ]
          },
          {
            "data": {
              "id": "d6y7olsu1aw0",
              "text": "段落间跳转"
            },
            "children": [
              {
                "data": {
                  "id": "d6y7oujccbs0",
                  "text": "{"
                },
                "children": [
                  {
                    "data": {
                      "id": "d6y7p6je88o0",
                      "text": "跳转到上一个空行"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "d6y7oxgdgwo0",
                  "text": "}"
                },
                "children": [
                  {
                    "data": {
                      "id": "d6y7oyc3xeg0",
                      "text": "跳转到下一个空行"
                    },
                    "children": []
                  }
                ]
              }
            ]
          },
          {
            "data": {
              "id": "cz7hngr4s680",
              "text": "7. 文档字符定位"
            },
            "children": [
              {
                "data": {
                  "id": "cz7hnjfr8dc0",
                  "text": "全文搜索"
                },
                "children": [
                  {
                    "data": {
                      "id": "cz88f7d8mwo0",
                      "text": "向下搜索"
                    },
                    "children": [
                      {
                        "data": {
                          "id": "cz88imyiymg0",
                          "text": "/string "
                        },
                        "children": [
                          {
                            "data": {
                              "id": "cz93d97y2sg0",
                              "text": "不区分大小写搜索\\cstring"
                            },
                            "children": []
                          },
                          {
                            "data": {
                              "id": "cz93dfwpvfc0",
                              "text": "区分大小写搜索\\Cstring"
                            },
                            "children": []
                          },
                          {
                            "data": {
                              "id": "cz93dltrhw00",
                              "text": "取消搜索高亮结果"
                            },
                            "children": [
                              {
                                "data": {
                                  "id": "cz93drm80000",
                                  "text": ":noh"
                                },
                                "children": []
                              }
                            ]
                          }
                        ]
                      },
                      {
                        "data": {
                          "id": "cz88inqemtk0",
                          "text": "g*"
                        },
                        "children": []
                      }
                    ]
                  },
                  {
                    "data": {
                      "id": "cz88iqe4z740",
                      "text": "向上搜索"
                    },
                    "children": [
                      {
                        "data": {
                          "id": "cz88itb1h5s0",
                          "text": "?string"
                        },
                        "children": []
                      },
                      {
                        "data": {
                          "id": "cz88iupu78o0",
                          "text": "g#"
                        },
                        "children": []
                      }
                    ]
                  },
                  {
                    "data": {
                      "id": "cz88fcvrvuo0",
                      "text": "？string 向上搜索"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "cz7i5gy74nc0",
                  "text": "向下查找光标下相同的单词 *"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz7i60s1oqg0",
                  "text": "向上查找光标下相同的单词#"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz7i6m2eu680",
                  "text": "切换到成对匹配的字符 %"
                },
                "children": []
              }
            ]
          },
          {
            "data": {
              "id": "cz8a3vomxi80",
              "text": "8.基于标记移动"
            },
            "children": [
              {
                "data": {
                  "id": "cz8a3xyf4v40",
                  "text": "跳转到上次跳转的地方 ``"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz8a46szgls0",
                  "text": "跳转到上次修改的地方 "
                },
                "children": [
                  {
                    "data": {
                      "id": "cz96hnqapm00",
                      "text": "`. 普通跳转"
                    },
                    "children": []
                  },
                  {
                    "data": {
                      "id": "cz96hr2twxc0",
                      "text": "gi跳转并进入到编辑模式"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "cz8a4pe45xc0",
                  "text": "跳转到上次插入的位置"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz8a53brnxs0",
                  "text": "新增标记m{a-z}"
                },
                "children": []
              }
            ]
          },
          {
            "data": {
              "id": "d73isal8t1k0",
              "text": "基于历史移动"
            },
            "children": [
              {
                "data": {
                  "id": "d73iseg5wy00",
                  "text": "移动到上次位置 Ctrl + o"
                },
                "children": []
              },
              {
                "data": {
                  "id": "d75o2pfg5ow0",
                  "text": "移动到前进位置 Ctrl + i"
                },
                "children": []
              }
            ]
          },
          {
            "data": {
              "id": "cz8bc6gsm2g0",
              "text": "9. 当前可视文档内移动"
            },
            "children": [
              {
                "data": {
                  "id": "cz8bcavquvs0",
                  "text": "移动到第一行 H"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz8bch9q4v40",
                  "text": "移动到最后一行 L"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz8bco3dl080",
                  "text": "移动到文档中间 M"
                },
                "children": []
              }
            ]
          },
          {
            "data": {
              "id": "czclo5qhb540",
              "text": "10.打开文件后立即定位到指定行"
            },
            "children": [
              {
                "data": {
                  "id": "czclodsy6ps0",
                  "text": "vim 文件名 +{行数}"
                },
                "children": [
                  {
                    "data": {
                      "id": "czcloor28dc0",
                      "text": "vim aaa.txt +100 定位到文件第100行"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "czcloyjtauo0",
                  "text": "如果没有行数默认定位到文档结尾"
                },
                "children": []
              }
            ]
          }
        ]
      },
      {
        "data": {
          "id": "cz7h54jop740",
          "text": "文档编辑"
        },
        "children": [
          {
            "data": {
              "id": "cz7hiaki42w0",
              "text": "基础操作"
            },
            "children": [
              {
                "data": {
                  "id": "cz7hh991n600",
                  "text": "向行尾插入字符并进入编辑模式"
                },
                "children": [
                  {
                    "data": {
                      "id": "cz7hhe2m1zs0",
                      "text": "A"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "cz7hgx0vw140",
                  "text": "向行首插入字符并进入编辑模式"
                },
                "children": [
                  {
                    "data": {
                      "id": "cz7hh7bimao0",
                      "text": "I"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "cz7hgcfmqxs0",
                  "text": "向上插入一行并进入编辑模式"
                },
                "children": [
                  {
                    "data": {
                      "id": "cz7hggnzab40",
                      "text": "O"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "cz7hg7aj7000",
                  "text": "向下插入一行并进入编辑模式"
                },
                "children": [
                  {
                    "data": {
                      "id": "cz7hgawarag0",
                      "text": "o"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "cz7hin2ogsg0",
                  "text": "在当前字符前进入编辑模式"
                },
                "children": [
                  {
                    "data": {
                      "id": "cz7hj9cbee00",
                      "text": "i"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "cz7hjaukl600",
                  "text": "在当前字符后进入编辑模式"
                },
                "children": [
                  {
                    "data": {
                      "id": "cz7hjg3se9s0",
                      "text": "a"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "cz92jdybjls0",
                  "text": "粘贴光标之前"
                },
                "children": [
                  {
                    "data": {
                      "id": "cz92jjdvjr40",
                      "text": "p（小写）"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "cz92jkyl0680",
                  "text": "粘贴光标之后"
                },
                "children": [
                  {
                    "data": {
                      "id": "cz92jpym6gw0",
                      "text": "P（大写）"
                    },
                    "children": []
                  }
                ]
              }
            ]
          },
          {
            "data": {
              "id": "cz7h6souvi00",
              "text": "行操作"
            },
            "children": [
              {
                "data": {
                  "id": "cz7h58srv600",
                  "text": "行复制黏贴"
                },
                "children": [
                  {
                    "data": {
                      "id": "cz7h5xkulkg0",
                      "text": "yy 复制一行"
                    },
                    "children": []
                  },
                  {
                    "data": {
                      "id": "cz7h60zqnbs0",
                      "text": "p黏贴一行"
                    },
                    "children": []
                  },
                  {
                    "data": {
                      "id": "d074zukbu800",
                      "text": "P向上粘贴"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "cz7h63oeaxk0",
                  "text": "行剪切"
                },
                "children": [
                  {
                    "data": {
                      "id": "cz7h688s1ts0",
                      "text": "dd 剪切一行"
                    },
                    "children": []
                  },
                  {
                    "data": {
                      "id": "d0752in6va00",
                      "text": "D 删除光标以及后面的字符串"
                    },
                    "children": []
                  },
                  {
                    "data": {
                      "id": "d6wisehijfk0",
                      "text": "C 删除光标以及后面的字符串并进入编辑模式"
                    },
                    "children": []
                  },
                  {
                    "data": {
                      "id": "dczs8c9n7hk0",
                      "text": "cc/S 清空当前行并进入编辑模式"
                    },
                    "children": []
                  },
                  {
                    "data": {
                      "id": "d6wczxb1vps0",
                      "text": "J 删除当前末尾的换行符"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "cz7hkd46vtk0",
                  "text": "可视化操作"
                },
                "children": [
                  {
                    "data": {
                      "id": "cz7hkhszmxs0",
                      "text": "按光标范围选择"
                    },
                    "children": [
                      {
                        "data": {
                          "id": "cz7hko8u4m00",
                          "text": "v"
                        },
                        "children": []
                      }
                    ]
                  },
                  {
                    "data": {
                      "id": "cz7hktgnpr40",
                      "text": "按行选择"
                    },
                    "children": [
                      {
                        "data": {
                          "id": "cz7hkvkavr40",
                          "text": "V"
                        },
                        "children": []
                      }
                    ]
                  },
                  {
                    "data": {
                      "id": "cz7hl0i6t800",
                      "text": "按列选择"
                    },
                    "children": [
                      {
                        "data": {
                          "id": "cz7hl2vubu00",
                          "text": "Ctrl + v"
                        },
                        "children": []
                      }
                    ]
                  },
                  {
                    "data": {
                      "id": "cz93tiywjfc0",
                      "text": "范围选择可以结合$^"
                    },
                    "children": []
                  }
                ]
              },
              {
                "data": {
                  "id": "cz937k8glkw0",
                  "text": "行文本调整"
                },
                "children": [
                  {
                    "data": {
                      "id": "cz937oewkco0",
                      "text": "文本内容向左对齐"
                    },
                    "children": [
                      {
                        "data": {
                          "id": "cz937yyzag00",
                          "text": ":le（left）"
                        },
                        "children": []
                      }
                    ]
                  },
                  {
                    "data": {
                      "id": "cz93855ttk00",
                      "text": "文本内容居中对齐"
                    },
                    "children": [
                      {
                        "data": {
                          "id": "cz9389tiwi80",
                          "text": ":ce（center）"
                        },
                        "children": []
                      }
                    ]
                  },
                  {
                    "data": {
                      "id": "cz938embyzk0",
                      "text": "文本内容向右对齐"
                    },
                    "children": [
                      {
                        "data": {
                          "id": "cz938n4t46g0",
                          "text": ":ri（right）"
                        },
                        "children": []
                      }
                    ]
                  }
                ]
              },
              {
                "data": {
                  "id": "dhv8dzgrf2g0",
                  "text": "多行操作"
                },
                "children": [
                  {
                    "data": {
                      "id": "dhv8e2nfi3s0",
                      "text": "Ctrl + V 进入多列编辑"
                    },
                    "children": [
                      {
                        "data": {
                          "id": "dhv8egiovwg0",
                          "text": "Shift + I 多行插入"
                        },
                        "children": []
                      },
                      {
                        "data": {
                          "id": "dhv8iowuqi00",
                          "text": "c 多行编辑"
                        },
                        "children": []
                      },
                      {
                        "data": {
                          "id": "dhv8euoqu1s0",
                          "text": "V 进入多行选择"
                        },
                        "children": []
                      }
                    ]
                  }
                ]
              }
            ]
          },
          {
            "data": {
              "id": "cz7h7fewm5k0",
              "text": "字符操作"
            },
            "children": [
              {
                "data": {
                  "id": "cz7h7ic6vts0",
                  "text": "x删除光标字符"
                },
                "children": []
              },
              {
                "data": {
                  "id": "dczhbsju9880",
                  "text": "X删除光标前面的字符"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz7h7m2k4lc0",
                  "text": "r替换光标字符"
                },
                "children": []
              },
              {
                "data": {
                  "id": "d074w01qhe80",
                  "text": "R替换模式"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz7hufdfzjs0",
                  "text": "s删除当前字符并进入编辑模式"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz7huje6ifc0",
                  "text": "S删除当前行并进入编辑模式 | cc 一样的效果"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz7hv3ufiaw0",
                  "text": "D删除当前光标到最后一行的字符"
                },
                "children": []
              },
              {
                "data": {
                  "id": "cz7hvtbikv40",
                  "text": "C 删除当前光标到最后一行字符并进入编辑模式"
                },
                "children": []
              }
            ]
          },
          {
            "data": {
              "id": "cz8b7vl4ubc0",
              "text": "替换"
            },
            "children": [
              {
                "data": {
                  "id": "cz8b7x6x3m00",
                  "text": ":%s/aaa/bbb/gc"
                },
                "children": [
                  {
                    "data": {
                      "id": "cz8b824enoo0",
                      "text": "%表示对整个文档进行操作，默认只会当前行有效，相当于 1,$"
                    },
                    "children": []
                  },
                  {
                    "data": {
                      "id": "czclqx7gnfk0",
                      "text": "g表示全局替换，默认只替换第一个匹配的字符"
                    },
                    "children": []
                  },
                  {
                    "data": {
                      "id": "czclr418gh40",
                      "text": "c表示每次替换前都会二次确认"
                    },
                    "children": []
                  },
                  {
                    "data": {
                      "id": "czclibj6a3k0",
                      "text": "1,100 表示从第一行到第100行"
